export const canvasJa = Object.fromEntries(
  Object.keys({ ...scenarioTitlesJa, ...canvasJaBase }).map((id) => [id, { ...(scenarioTitlesJa[id] ? { title: scenarioTitlesJa[id] } : {}), ...(canvasJaBase[id] || {}) }]),
);
